"""Higher-dimensional cones: spectra, rigidity, and the orbit decomposition.

Enumerates the kernel spectrum of  x_1^2 + ... + x_k^2 = y^2  for k = 2, 3, 4;
verifies hypotenuse-leg rigidity and the count k+1 of hypotenuse-merged
patterns; and decomposes the missing patterns of the three-leg cone into orbits
under permutations of the legs.
"""

from __future__ import annotations

from itertools import permutations, product
from math import isqrt
from typing import Dict, List, Set, Tuple

Pattern = Tuple[int, ...]


def canonical_pattern(t: Tuple[int, ...]) -> Pattern:
    first: Dict[int, int] = {}
    out: List[int] = []
    for i, v in enumerate(t):
        if v not in first:
            first[v] = i
        out.append(first[v])
    return tuple(out)


def all_patterns(n: int) -> List[Pattern]:
    return sorted({canonical_pattern(t) for t in product(range(n), repeat=n)})


def bell(n: int) -> int:
    row = [1]
    for _ in range(n):
        nxt = [row[-1]]
        for x in row:
            nxt.append(nxt[-1] + x)
        row = nxt
    return row[0]


def cone_spectrum(k: int, bound: int) -> Set[Pattern]:
    spec: Set[Pattern] = set()
    for legs in product(range(bound + 1), repeat=k):
        s = sum(x * x for x in legs)
        y = isqrt(s)
        if y * y == s:
            spec.add(canonical_pattern(legs + (y,)))
    return spec


def merged_patterns(spec: Set[Pattern], k: int) -> Set[Pattern]:
    """Patterns in which the last coordinate shares a block with a leg."""
    return {p for p in spec if p[k] != k}


def leg_orbits(patterns: Set[Pattern], k: int) -> List[List[Pattern]]:
    """Orbits of a set of patterns under permutations of the k legs."""
    remaining = set(patterns)
    orbits: List[List[Pattern]] = []
    while remaining:
        p = min(remaining)
        orb: Set[Pattern] = set()
        for sigma in permutations(range(k)):
            permuted = tuple(p[sigma[i]] for i in range(k)) + (p[k],)
            orb.add(canonical_pattern(permuted))
        orbits.append(sorted(orb))
        remaining -= orb
    return orbits


def check_rigidity(k: int, bound: int) -> bool:
    for legs in product(range(bound + 1), repeat=k):
        s = sum(x * x for x in legs)
        y = isqrt(s)
        if y * y != s:
            continue
        for j in range(k):
            if legs[j] == y and any(legs[i] != 0 for i in range(k) if i != j):
                return False
    return True


def main() -> None:
    print("k   Bell(k+1)   |Spec|   merged   predicted by the dimension formula")
    for k, bound in ((2, 60), (3, 40), (4, 25)):
        spec = cone_spectrum(k, bound)
        merged = merged_patterns(spec, k)
        predicted = (k + 1) + (bell(k) - (0 if isqrt(k) ** 2 == k else 1))
        print(f"{k}   {bell(k+1):>9}   {len(spec):>6}   {len(merged):>6}   {predicted:>6}")
        assert len(merged) == k + 1, "merged part should have exactly k+1 elements"

    print("\nHypotenuse-leg rigidity (if the hypotenuse equals a leg, all other legs vanish):")
    for k, bound in ((2, 120), (3, 50), (4, 22)):
        print(f"  k = {k}: verified up to {bound} -> {check_rigidity(k, bound)}")

    k = 3
    spec = cone_spectrum(k, 40)
    missing = set(all_patterns(k + 1)) - spec
    print(f"\nThe cone x^2+y^2+z^2 = w^2 realises {len(spec)} of {bell(4)} patterns; "
          f"{len(missing)} are missing.")
    print("Orbits of the missing patterns under permutations of the three legs:")
    for orb in leg_orbits(missing, k):
        tag = ("all legs equal, hypotenuse apart" if len(orb) == 1
               else "rigidity-blocked family")
        print(f"  size {len(orb)}: " + ", ".join("".join(map(str, p)) for p in orb)
              + f"    [{tag}]")
    sizes = sorted(len(o) for o in leg_orbits(missing, k))
    print(f"Orbit sizes: {sizes}  (a symmetric obstruction of size 1, "
          f"two asymmetric families of size 3)")


if __name__ == "__main__":
    main()

