"""Canonicalisation of equality patterns and enumeration of all patterns."""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Sequence, Set, Tuple


def canonical_pattern(t: Sequence[int]) -> Tuple[int, ...]:
    """Return the canonical form of a tuple.

    Entry i of the canonical form is the least index j with t[j] == t[i].
    Two tuples have equal canonical forms exactly when their coordinates
    coincide in the same places, i.e. when they induce the same partition of
    the index set.  Cost: O(n) with a hash map.
    """
    first: Dict[int, int] = {}
    out: List[int] = []
    for i, v in enumerate(t):
        if v not in first:
            first[v] = i
        out.append(first[v])
    return tuple(out)


def all_patterns(n: int) -> List[Tuple[int, ...]]:
    """All canonical patterns of length n (equivalently, all set partitions)."""
    seen: Set[Tuple[int, ...]] = set()
    for t in product(range(n), repeat=n):
        seen.add(canonical_pattern(t))
    return sorted(seen)


def bell(n: int) -> int:
    """The n-th Bell number, computed by the Bell triangle in O(n^2)."""
    row: List[int] = [1]
    for _ in range(n):
        nxt = [row[-1]]
        for x in row:
            nxt.append(nxt[-1] + x)
        row = nxt
    return row[0]


def refines(p: Sequence[int], q: Sequence[int]) -> bool:
    """True iff every coincidence of p is a coincidence of q (p refines q)."""
    n = len(p)
    return all(q[i] == q[j] for i in range(n) for j in range(n) if p[i] == p[j])


if __name__ == "__main__":
    for n in range(1, 6):
        assert len(all_patterns(n)) == bell(n)
        print(f"n = {n}:  {bell(n)} patterns")
    print("chain 012 < 002 < 000:",
          refines((0, 1, 2), (0, 0, 2)) and refines((0, 0, 2), (0, 0, 0)))

"""Decision procedure for the kernel spectrum of a ternary conic."""

from __future__ import annotations

from math import isqrt
from typing import Dict, Optional, Set, Tuple

Pattern = Tuple[int, ...]


def is_square(n: int) -> bool:
    """True iff n >= 0 is a perfect square; O(log n) via integer square root."""
    if n < 0:
        return False
    r = isqrt(n)
    return r * r == n


def conic_spectrum(A: int, B: int, C: int, search: int = 500
                   ) -> Tuple[Set[Pattern], Dict[Pattern, Optional[Tuple[int, int, int]]]]:
    """Kernel spectrum of  A x^2 + B y^2 = C z^2  with explicit witnesses.

    The four non-generic patterns are decided *exactly* by closed-form criteria:

        <000>  always realised (the origin);
        <002>  x = y != z  iff  (A+B) C is a perfect square and A + B != C;
        <010>  x = z != y  iff  A <= C, (C-A) B is a perfect square, A + B != C;
        <011>  y = z != x  iff  B <= C, (C-B) A is a perfect square, A + B != C.

    The discrete pattern <012> is decided by a bounded search: positive answers
    are certain, a negative answer only means "no small witness".
    """
    assert A > 0 and B > 0 and C > 0
    spec: Set[Pattern] = set()
    wit: Dict[Pattern, Optional[Tuple[int, int, int]]] = {}

    spec.add((0, 0, 0))
    wit[(0, 0, 0)] = (0, 0, 0)

    if is_square((A + B) * C) and A + B != C:
        m = isqrt((A + B) * C)
        spec.add((0, 0, 2))
        wit[(0, 0, 2)] = (C, C, m)          # (A+B) C^2 = C m^2

    if A <= C and is_square((C - A) * B) and A + B != C:
        m = isqrt((C - A) * B)
        spec.add((0, 1, 0))
        wit[(0, 1, 0)] = (B, m, B)          # (C-A) B^2 = B m^2

    if B <= C and is_square((C - B) * A) and A + B != C:
        m = isqrt((C - B) * A)
        spec.add((0, 1, 1))
        wit[(0, 1, 1)] = (m, A, A)          # (C-B) A^2 = A m^2

    for x in range(search + 1):
        for y in range(search + 1):
            lhs = A * x * x + B * y * y
            if lhs % C:
                continue
            z2 = lhs // C
            z = isqrt(z2)
            if z * z == z2 and len({x, y, z}) == 3:
                spec.add((0, 1, 2))
                wit[(0, 1, 2)] = (x, y, z)
                return spec, wit
    return spec, wit


def conic_defect(A: int, B: int, C: int) -> int:
    """5 minus the number of realised patterns."""
    return 5 - len(conic_spectrum(A, B, C)[0])


if __name__ == "__main__":
    for C in (50, 1, 8, 2, 3):
        spec, wit = conic_spectrum(1, 1, C)
        print(f"C = {C:>3}  defect = {5 - len(spec)}  witnesses = "
              + ", ".join(f"{''.join(map(str, p))}:{wit[p]}" for p in sorted(spec)))

