"""Equal-legs decision for the pencil A x^p + B y^p = C z^p."""

from __future__ import annotations

from typing import Optional, Tuple


def integer_root(n: int, p: int) -> Optional[int]:
    """Exact p-th root of n if it exists, else None.  O(log n) refinements."""
    if n < 0:
        return None
    if n in (0, 1):
        return n
    r = int(round(n ** (1.0 / p)))
    for cand in range(max(r - 2, 0), r + 3):
        if cand ** p == n:
            return cand
    lo, hi = 0, 1
    while hi ** p < n:
        hi *= 2
    while lo <= hi:
        mid = (lo + hi) // 2
        v = mid ** p
        if v == n:
            return mid
        if v < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return None


def equal_legs(p: int, A: int, B: int, C: int) -> Tuple[bool, bool, bool,
                                                        Optional[Tuple[int, int, int]]]:
    """Decide the equal-legs pattern for A x^p + B y^p = C z^p.

    Returns (power_condition, non_degeneracy, realised, witness).  The pattern
    x = y != z is realised precisely when (A+B) C^(p-1) is a p-th power *and*
    A + B != C; a witness is then (C, C, r) with (A+B) C^(p-1) = r^p.
    """
    assert p >= 1 and C > 0
    r = integer_root((A + B) * C ** (p - 1), p)
    power = r is not None
    nondeg = (A + B) != C
    if power and nondeg:
        return True, True, True, (C, C, r)  # type: ignore[return-value]
    return power, nondeg, False, None


if __name__ == "__main__":
    for C in (1, 2, 16, 54):
        print(f"p = 3, C = {C:>3}:", equal_legs(3, 1, 1, C))
    for p in (2, 3, 4, 5, 6):
        print(f"x^{p} + y^{p} = z^{p}:", equal_legs(p, 1, 1, 1))
